// The instrument check: every target must occur exactly once in the current sources. `--check` runs only this (fast, no build, no tests);
// a normal run does it first, so a list that cannot run fails before any baseline. MUTATION_CHECK_SELFTEST=1 adds a target that
// cannot match, so the gate can prove that a broken instrument turns the check red.
if (process.env.MUTATION_CHECK_SELFTEST === "1") MUTANTS.push(["ZZ-SELFTEST a target that does not occur", "src/cli.ts", "this text does not occur in the sources\u0000", "x"]);
{
  const checked = reportInstrumentCheck("mutation controls", checkMutantTargets(MUTANTS, (file) => readFileSync(join(root, file), "utf8")));
  if (checked !== 0 || process.argv.includes("--check")) process.exit(checked);
}

/** Wall-clock cap for one suite run (a mutant that loops forever must not hang the gate). Null status from a run that hit it is SUSPECT. */
const RUN_CAP_MS = Number(process.env.MUTATION_RUN_CAP_MINUTES || 30) * 60 * 1000;

/**
 * Runs one suite in a scratch directory without blocking, so several mutants can run at once. The verdict is read from vitest's
 * own JSON result file (see scripts/kill-rule.mjs), never from what the run printed. With MUTATION_JOBS above 1, timing-sensitive
 * tests can time out under load; such a run is SUSPECT, not a kill: rerun it with MUTATION_JOBS=1.
 */
async function run(dir) {
  const resultPath = join(dir, ".kill-rule-result.json");
  const r = await runWithCap("npx", ["vitest", "run", "--reporter=json", `--outputFile=${resultPath}`], { cwd: dir, env: { ...process.env, CI: "1" }, timeoutMs: RUN_CAP_MS });
  return { ...r, parsed: readResult(resultPath, parseVitestJson) };
}

function scratch() {
  const dir = mkdtempSync(join(tmpdir(), "pg-mutation-"));
  // Everything the main suite reads: sources, tests, schemas, scripts, docs, the demo fixtures and the operator documents.
  const items = ["src", "tests", "schemas", "scripts", "docs", "fixtures", "package.json", "tsconfig.json", "tsconfig.build.json", "vitest.config.ts"];
  items.push("README.md", "CHANGELOG.md", "SECURITY.md", "CONTRIBUTING.md", "SECURITY.md", "LICENSE", "Dockerfile", ".dockerignore");
  for (const item of new Set(items)) cpSync(join(root, item), join(dir, item), { recursive: true });
  symlinkSync(join(root, "node_modules"), join(dir, "node_modules"));
  return dir;
}

// The unmutated baseline must be green, otherwise a red mutant proves nothing.
const base = scratch();
const baseline = await run(base);
console.log(`baseline (unmutated): exit ${baseline.code}, ${baseline.parsed?.failed ?? "no result"} failing tests`);
rmSync(base, { recursive: true, force: true });
if (baseline.code !== 0) {
  console.error("baseline is not green; controls are meaningless\n" + baseline.output.slice(-2000));
  process.exit(1);
}

// Mutants are independent (each has its own scratch copy and build), so run a few at a time.
const jobs = Math.max(1, Number(process.env.MUTATION_JOBS) || Math.min(4, cpus().length));
let bad = 0;
let next = 0;
async function worker() {
  while (next < MUTANTS.length) {
    const [name, file, find, replace] = MUTANTS[next++];
    const dir = scratch();
    const path = join(dir, file);
    const text = readFileSync(path, "utf8");
    const count = text.split(find).length - 1;
    if (count !== 1) {
      console.log(`FAIL ${name}: expected exactly one match of the mutation target in ${file}, found ${count}`);
      bad += 1;
      rmSync(dir, { recursive: true, force: true });
      continue;
    }
    writeFileSync(path, text.replace(find, () => replace));
    const result = await run(dir);
    // A mutant only counts as killed by a FAILING TEST. A red run with no failing test (a mutant that no longer compiles, a
    // crashed worker) proves nothing about the tests, so it is reported as SUSPECT and counted as a control that did not bite.
    // The shared rule (scripts/kill-rule.mjs) also treats a run whose every failure was a timeout as SUSPECT, and names the first
    // failing test, so a kill is attributed to a test. With MUTATION_JOBS above 1 timing-sensitive tests can time out under
    // load; such a run proves nothing and is rerun with fewer jobs (MUTATION_JOBS=1).
    const label = classify(result);
    console.log(describeResult(label, name, result));
    if (label !== "KILLED") bad += 1;
    rmSync(dir, { recursive: true, force: true });
  }
}
await Promise.all(Array.from({ length: jobs }, worker));
console.log(bad === 0 ? `all ${MUTANTS.length} mutants killed` : `${bad} control(s) did not bite`);
process.exit(bad === 0 ? 0 : 1);
